const icon=k=>`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${icons[k]||icons.lock}"/></svg>`;
const btn=(text,to,primary=false)=>`<button ${primary?'class="primary"':''} data-go="${to}">${text}</button>`;
const actions=(...v)=>`<div class="actions">${v.join('')}</div>`;
const tag=t=>`<span class="tag">${t}</span>`;
const card=(title,body)=>`<section class="card"><h2>${title}</h2>${body}</section>`;
const map=()=>`<div class="map"><svg viewBox="0 0 600 350" preserveAspectRatio="xMidYMid slice"><path fill="#2e5058" d="M410 0H600V350H380Q480 240 410 0"/><g fill="none" stroke="#657c77" stroke-width="12"><path d="M300-20Q460 120 300 230T310 400"/><path d="M-10 250 360 180M50 0 250 350"/></g><path fill="none" stroke="#e4b578" stroke-width="5" d="M300-20Q460 120 300 230T310 400"/></svg><span class="map-label">안목해변 · 강릉</span><div class="pin">♪</div><span class="map-caption">설명용 지도 · 실제 위치 아님</span></div>`;
const wave=()=>`<div class="wave" aria-hidden="true">${[14,30,24,48,65,40,30,55,72,44,24,60,48,24,40,68,36,22,46,60,28,16].map(h=>`<i style="height:${h}px"></i>`).join('')}</div>`;
const center=(ic,title,desc,cta)=>`<div class="center"><div class="hero-icon">${icon(ic)}</div><h1>${title}</h1><p>${desc}</p>${cta||''}</div>`;
