const capsuleArt=()=>`<div class="capsule-art" aria-label="바다에 남긴 목소리의 추상 표지"><svg viewBox="0 0 400 400" aria-hidden="true"><circle cx="200" cy="185" r="112" fill="none" stroke="currentColor" stroke-width="1"/><circle cx="200" cy="185" r="83" fill="none" stroke="currentColor" stroke-width="1"/><path d="M0 260Q100 210 200 260T400 260M0 282Q100 232 200 282T400 282M0 304Q100 254 200 304T400 304" fill="none" stroke="currentColor" stroke-width="2"/><path d="M167 175v20m13-38v56m13-70v84m14-66v48m13-34v20m13-44v68" stroke="currentColor" stroke-width="7" stroke-linecap="round"/></svg><span>안목해변<br><b>2027.08.15</b></span></div>`;
const eligibility=()=>`<div class="eligibility">${[['near','장소',state.near?'안목해변 도착':'안목해변에서 열림'],['date','개봉일',state.date?'개봉일이 지났어요':'2045.08.15부터'],['access','받는 사람',state.access?'수신 권한 확인':'수신 권한 필요']].map(([key,label,text])=>`<div class="eligibility-row">${icon(state[key]?'check':'lock')}<div><small>${label}</small><strong>${text}</strong></div><span>${state[key]?'충족':'대기'}</span></div>`).join('')}</div>`;
function replaceScene(id,fn){scenes.find(s=>s[0]===id)[3]=fn}
replaceScene('home',()=>`<div class="section-heading"><div><div class="eyebrow">오늘의 여행 · 2027.08.15</div><h1>이 순간을, 이 길에.</h1></div><span class="quiet-label">안목해변</span></div><div class="home-grid"><section class="record-invitation"><div class="invitation-icon">${icon('mic')}</div><div><h2>오늘의 목소리 남기기</h2><p>최대 30초, 그날의 장소와 함께.</p></div>${btn('목소리 남기기','consent',true)}<small>녹음은 직접 시작할 때만 켜져요.</small></section><section class="journey-preview">${map()}<div class="journey-caption"><div><small>이번 여행</small><h2>우리의 여름 바다</h2><p>캡슐 3개 · 각 장소에서 열림</p></div>${btn('여행 보기','album')}</div></section></div>`);
replaceScene('library',()=>`<div class="section-heading"><div><div class="eyebrow">내 캡슐 · 3개</div><h1>길 위에서 기다리는 목소리</h1></div></div><div class="capsule-list">${[['detail','바다 냄새 나!','안목해변 · 18초','하윤에게 · 2045.08.15부터','clock'],['forest','숲을 지나며','대관령 · 24초','나만 듣기 · 현장에서 열림','lock'],['sunset','노을 앞의 약속','경포 · 12초','가족에게 · 현장에서 열림','people']].map(([id,title,meta,status,ic],i)=>`<button class="capsule-row" data-go="${id}"><span class="capsule-number">0${i+1}</span><span class="capsule-text"><strong>${title}</strong><small>${meta}</small></span><span class="capsule-status">${icon(ic)}${status}</span><span aria-hidden="true">›</span></button>`).join('')}</div>`);
replaceScene('detail',()=>`<div class="detail-grid"><div>${capsuleArt()}</div><div><div class="eyebrow">아빠가 하윤에게 · 18초</div><h1>바다 냄새 나!</h1><p class="detail-sub">이 목소리가 열리는 세 가지 조건</p>${eligibility()}${actions(btn('개봉 조건 확인','unlock',true),btn('이 장소로 안내','route'))}<button class="text-action" data-go="manage">캡슐 관리</button></div></div>`);
replaceScene('play',()=>`<div class="player-grid">${capsuleArt()}<section class="player-content"><div class="eyebrow">현장에서 듣는 중 · 2045년 시나리오</div><h1>바다 냄새 나!</h1><p>아빠가 하윤에게 남긴 목소리</p><div class="memory-context">2027.08.15 · 비 오던 밤</div><div class="progress" role="progressbar" aria-label="재생 위치" aria-valuenow="7" aria-valuemin="0" aria-valuemax="18"><div></div></div><div class="row"><small>00:07</small><small>00:18</small></div><div class="player-actions">${btn('그만 듣기','detail')}<button class="primary playback-main" data-go="paused">${icon('pause')}<span>일시 정지</span></button></div><small class="player-note">이 장소를 벗어나면 재생이 멈춰요.</small></section></div>`);
replaceScene('record',()=>`<div class="recording-layout"><div class="eyebrow"><span class="record-dot"></span> 녹음 중 · 안목해변</div><h1>지금의 목소리를 남겨요</h1><div class="timer">00:18 <span>/ 00:30</span></div>${wave()}<p>최대 30초까지 담을 수 있어요.</p><div class="record-actions">${btn('취소','home')}<button class="primary stop-recording" data-go="review"><span class="stop-square"></span>녹음 마치기</button></div><small>마이크를 사용하지 않는 화면 시연입니다.</small></div>`);
const originalUnlock=unlock;
unlock=()=>`<div class="unlock-layout"><div><div class="eyebrow">바다 냄새 나! · 편지 캡슐</div><h1>${!state.access?'받는 사람의 권한이 필요해요':!state.date?'2045년 8월 15일부터 열 수 있어요':!state.near?'안목해변에서만 들을 수 있어요':'이 장소에서 열 수 있어요'}</h1><p>목소리는 세 가지 조건이 모두 맞을 때 열려요.</p>${actions(btn(state.near&&state.date&&state.access?'캡슐 열기':'다시 확인',state.near&&state.date&&state.access?'arrival':'unlock',true),btn('상세로','detail'))}</div>${eligibility()}</div>`;
const sectionFor=id=>{if(['home','welcome','permission','consent','record','review','tags','conditions','saved'].includes(id))return 'home';if(['album','share','shared','route','route-sent'].includes(id))return 'album';if(['family','invite','invited','follow'].includes(id))return 'family';if(['settings','sync','unlink','subscription'].includes(id))return 'settings';return 'library'};

window.scenes=scenes;let current=location.hash.slice(1)||'home';const ids=['driving','near','date','access','interrupt'];const state={};ids.forEach(id=>{state[id]=document.getElementById(id).checked});
function unlock(){let why=!state.access?'받는 사람의 권한이 필요해요':!state.date?'2045년 8월 15일부터 열 수 있어요':!state.near?'안목해변에서만 들을 수 있어요':'';return why?center('lock',why,'장소 · 개봉일 · 수신 권한을 모두 확인합니다.',actions(btn('다시 확인','unlock',true),btn('상세로','detail'))):center('check','이 장소에서 열 수 있어요','현재 위치와 개봉일, 수신 권한을 확인했어요.',actions(btn('캡슐 열기','arrival',true)));}
function canPlay(){return state.near&&state.date&&state.access&&!state.interrupt&&!state.driving}
function render(){let display=current;if(state.driving)display='driving';else if(['play','arrival','paused'].includes(current)){if(!state.near)display='outside';else if(!state.date||!state.access)display='unlock';else if(state.interrupt)display='interrupted';}const s=scenes.find(s=>s[0]===display)||scenes[2];document.getElementById('scene').value=current;document.getElementById('app').innerHTML=`<div class="app-header"><div class="brand"><span class="logo">◷</span>타임캡슐</div><div class="status">${display==='driving'?'주행 중':'주차 확인 · 시연'}</div></div><div class="layout">${display==='driving'?'':`<nav class="rail" aria-label="앱 메뉴">${[['home','홈','home'],['library','캡슐','clock'],['album','여행','route'],['family','가족','people'],['settings','설정','settings']].map(([id,label,ic])=>`<button ${sectionFor(current)===id?'aria-current="page"':''} class="${sectionFor(current)===id?'active':''}" data-go="${id}">${icon(ic)}${label}</button>`).join('')}</nav>`}<article class="content scene-${display}">${s[3]()}</article></div>`;document.getElementById('note').textContent=`${s[1]} · ${s[2]} | 웹 디자인 시연입니다. 차량 상태·위치·녹음·재생·동기화는 실제 SDK와 연결되지 않았습니다.`;document.querySelectorAll('[data-go]').forEach(b=>b.onclick=()=>go(b.dataset.go));const unf=document.getElementById('unfollow');if(unf)unf.onclick=()=>{unf.textContent='친구 연결 해제됨 · 시연';unf.disabled=true};const sy=document.getElementById('sync-enable');if(sy)sy.onclick=()=>{sy.textContent='동기화 켜짐 · 시연';sy.disabled=true};}
function go(id){current=id;history.replaceState(null,'','#'+id);render();document.getElementById('app').scrollTop=0;}window.go=go;window.canPlay=canPlay;window.state=state;
document.getElementById('scene').innerHTML=scenes.map(s=>`<option value="${s[0]}">${s[1]}</option>`).join('');document.getElementById('scene').onchange=e=>go(e.target.value);ids.forEach(id=>document.getElementById(id).onchange=e=>{state[id]=e.target.checked;if(['play','arrival','paused'].includes(current)){if(state.driving)current='paused';else if(!state.near)current='outside';else if(!state.date||!state.access)current='unlock';else if(state.interrupt)current='interrupted';}render()});document.getElementById('theme').onclick=()=>{document.body.classList.toggle('day');document.getElementById('theme').textContent=document.body.classList.contains('day')?'야간 모드':'주간 모드'};document.getElementById('split').onclick=()=>{document.body.classList.toggle('split');document.getElementById('split').textContent=document.body.classList.contains('split')?'전체 창':'분할 창'};if(new URLSearchParams(location.search).has('capture'))document.body.classList.add('capture');render();
